'use strict';
// The supplied mark stays a separate placement from the two sleeve designs.
const bottomDefaults={enabled:false,surface:'underside',width:21,height:15.71,centerX:14,centerZ:1,depthMm:.4,relief:'raised'};
let bottomBrand={...bottomDefaults},bottomMask=null,bottomDrag=null,bottomGhost=null;
const bottomPanel=document.createElement('section');bottomPanel.className='panel';bottomPanel.id='bottomBrandPanel';
bottomPanel.innerHTML=`<details id="bottomBrandDetails"><summary>Design Mainline · bottom branding</summary><div><img src="branding/design-mainline.png" alt="Design Mainline logo" style="width:110px;max-height:90px;object-fit:contain;background:white;border-radius:5px"><label class="check"><input id="bottomBrandEnabled" type="checkbox" disabled><span>Add Design Mainline logo</span></label><label for="bottomBrandSurface">Print on</label><select id="bottomBrandSurface"><option value="underside">Underside of sleeve</option><option value="inside">Inside bottom</option></select><label for="bottomBrandWidth">Logo width (mm)</label><input id="bottomBrandWidth" type="number" min="4" max="60" step=".5"><label for="bottomBrandHeight">Logo height (mm)</label><input id="bottomBrandHeight" type="number" min="4" max="36" step=".5"><label for="bottomBrandDepth">Bottom depth (mm)</label><input id="bottomBrandDepth" type="number" min=".01" max="3" step=".01"><label for="bottomBrandRelief">Bottom finish</label><select id="bottomBrandRelief"><option value="raised">Emboss</option><option value="carved">Deboss</option></select><button class="btn btn-ghost" id="bottomBrandView" type="button">View bottom logo</button><button class="btn btn-ghost btn-sm" id="bottomBrandCenter" type="button">Fit logo to this surface</button><p class="muted-tip">Hold the mouse wheel on this logo and drag to position it. Has its own depth and emboss/deboss setting. Openings and edge margins are protected. The inside floor uses a smaller starting size; check the tiny lettering in your slicer.</p><p class="muted-tip" id="bottomBrandStatus" role="status">Loading your logo…</p></div></details>`;
document.querySelector('.template-select-panel').after(bottomPanel);
function syncBottomBrand(){bottomPanel.hidden=!templateActive();$('bottomBrandEnabled').checked=bottomBrand.enabled;$('bottomBrandSurface').value=bottomBrand.surface;$('bottomBrandWidth').value=bottomBrand.width;$('bottomBrandHeight').value=bottomBrand.height;$('bottomBrandDepth').value=bottomBrand.depthMm;$('bottomBrandRelief').value=bottomBrand.relief;$('bottomBrandView').textContent=bottomBrand.enabled?'View bottom logo':'Add & view bottom logo';}
function restoreBottomBrand(saved){bottomBrand={...bottomDefaults,...saved};syncBottomBrand();}
function fitBottomBrand(){Object.assign(bottomBrand,bottomBrand.surface==='inside'?{width:13,height:9.725,centerX:15.5,centerZ:7}:{width:21,height:15.71,centerX:14,centerZ:1});}
function bottomChanged(){syncBottomBrand();if(bottomBrand.enabled)$('bottomBrandStatus').textContent='Forming the logo on the '+(bottomBrand.surface==='inside'?'inside bottom':'underside')+'…';requestTemplatePreview();dirty();}
$('bottomBrandEnabled').onchange=e=>{bottomBrand.enabled=e.target.checked;bottomChanged();if(bottomBrand.enabled)viewBottomBrand();else $('bottomBrandStatus').textContent='Bottom logo is off. Choose Add & view bottom logo to place it.';};
$('bottomBrandSurface').onchange=e=>{bottomBrand.surface=e.target.value;fitBottomBrand();bottomChanged();viewBottomBrand();};
for(const [id,key,min,max]of [['bottomBrandWidth','width',4,60],['bottomBrandHeight','height',4,36]])$(id).onchange=e=>{const n=Number(e.target.value);if(Number.isFinite(n))bottomBrand[key]=Math.max(min,Math.min(max,n));bottomChanged();};
$('bottomBrandDepth').onchange=e=>{bottomBrand.depthMm=Math.max(.01,Math.min(3,Number(e.target.value)||.4));bottomChanged();};
$('bottomBrandRelief').onchange=e=>{bottomBrand.relief=e.target.value;bottomChanged();};
$('bottomBrandCenter').onclick=()=>{fitBottomBrand();bottomChanged();};
function viewBottomBrand(){if(!camera||!controls||!templateBase)return;setTemplateMove(false);if(gridHelper)gridHelper.visible=false;const inside=bottomBrand.surface==='inside';camera.up.set(0,0,1);controls.target.set(0,inside?10:0,0);camera.position.set(0,inside?170:-120,0);camera.lookAt(controls.target);controls.update();}
$('bottomBrandView').onclick=()=>{if(!bottomMask){$('bottomBrandStatus').textContent='The logo is still loading. Try again in a moment.';return;}if(!bottomBrand.enabled){bottomBrand.enabled=true;bottomChanged();}viewBottomBrand();};
const bottomOriginalView=templateView;templateView=function(which){if(camera)camera.up.set(0,1,0);if(gridHelper)gridHelper.visible=true;bottomOriginalView(which);};
const bottomOriginalOptions=templateOptions;templateOptions=function(detail=768){const o=bottomOriginalOptions(detail);if(bottomBrand.enabled){if(!bottomMask)throw Error('The Design Mainline logo is still loading. Try again in a moment.');o.designs.push({surface:bottomBrand.surface,maxHeight:bottomBrand.depthMm,negative:bottomBrand.relief==='carved',sharp:true,centerX:bottomBrand.centerX,centerZ:bottomBrand.centerZ,designWidth:bottomBrand.width,designHeight:bottomBrand.height,designRotation:0,designY:0,heightmap:bottomMask.hm,rows:bottomMask.rows,cols:bottomMask.cols});o.sharp=true;}return o;};
const bottomOriginalHas=hasSleeveArtwork;hasSleeveArtwork=function(){return bottomOriginalHas()||bottomBrand.enabled;};
const bottomOriginalSync=syncTemplateUI;syncTemplateUI=function(){bottomOriginalSync();syncBottomBrand();if(templateActive())$('templateStart').hidden=hasSleeveArtwork();};
const bottomOriginalReplace=replaceTemplateMesh;replaceTemplateMesh=function(...args){hideBottomGhost();bottomOriginalReplace(...args);};
function hideBottomGhost(){if(bottomGhost)bottomGhost.visible=false;}
function showBottomGhost(){if(!scene||!bottomMask)return;if(!bottomGhost){const canvas=document.createElement('canvas');canvas.width=bottomMask.cols;canvas.height=bottomMask.rows;const ctx=canvas.getContext('2d'),data=ctx.createImageData(canvas.width,canvas.height);for(let i=0;i<bottomMask.hm.length;i++){data.data[i*4]=255;data.data[i*4+1]=115;data.data[i*4+2]=0;data.data[i*4+3]=Math.round(bottomMask.hm[i]*255);}ctx.putImageData(data,0,0);bottomGhost=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(canvas),transparent:true,depthTest:false,side:THREE.DoubleSide}));bottomGhost.renderOrder=100;scene.add(bottomGhost);}bottomGhost.rotation.set(bottomBrand.surface==='inside'?-Math.PI/2:Math.PI/2,0,bottomBrand.surface==='inside'?Math.PI:0);bottomGhost.scale.set(bottomBrand.width,bottomBrand.height,1);bottomGhost.position.set(bottomBrand.centerX,bottomBrand.surface==='inside'?10.15:-.15,bottomBrand.centerZ);bottomGhost.visible=true;}
function bottomPointerHit(e){if(!templateActive()||!bottomBrand.enabled||!bottomMask||!templateRayMesh||exportBusy)return null;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObject(templateRayMesh,false)[0];if(!hit||hit.point.y>12||(bottomBrand.surface==='inside'?hit.face.normal.y<.95:hit.face.normal.y>-.95))return null;return hit.point;}
function bottomArtworkAt(p){const u=(bottomBrand.surface==='inside'?-1:1)*(p.x-bottomBrand.centerX)/bottomBrand.width+.5,v=.5-(p.z-bottomBrand.centerZ)/bottomBrand.height;if(u<0||u>1||v<0||v>1)return false;return bottomMask.hm[Math.round(v*(bottomMask.rows-1))*bottomMask.cols+Math.round(u*(bottomMask.cols-1))]>.25;}
// Capture on the parent before OrbitControls sees a middle-button press.
const bottomContainer=$('threeContainer');
bottomContainer.addEventListener('pointerdown',e=>{if(e.button!==1)return;const p=bottomPointerHit(e);if(!p||!bottomArtworkAt(p))return;e.preventDefault();e.stopImmediatePropagation();bottomDrag={id:e.pointerId,x:p.x-bottomBrand.centerX,z:p.z-bottomBrand.centerZ,enabled:controls.enabled};controls.enabled=false;bottomContainer.setPointerCapture(e.pointerId);showBottomGhost();templateStatus('Moving bottom logo · release the scroll wheel to place it.');},true);
bottomContainer.addEventListener('pointermove',e=>{if(!bottomDrag||bottomDrag.id!==e.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const p=bottomPointerHit(e);if(!p)return;bottomBrand.centerX=Math.max(-32,Math.min(32,p.x-bottomDrag.x));bottomBrand.centerZ=Math.max(-20,Math.min(20,p.z-bottomDrag.z));showBottomGhost();},true);
function finishBottomDrag(e){if(!bottomDrag||e.pointerId!==bottomDrag.id)return;e.preventDefault?.();e.stopImmediatePropagation?.();controls.enabled=bottomDrag.enabled;bottomDrag=null;if(bottomContainer.hasPointerCapture(e.pointerId))bottomContainer.releasePointerCapture(e.pointerId);bottomChanged();}
for(const type of ['pointerup','pointercancel','lostpointercapture'])bottomContainer.addEventListener(type,finishBottomDrag,true);
window.addEventListener('blur',()=>{if(bottomDrag)finishBottomDrag({pointerId:bottomDrag.id});});
const bottomOriginalPick=selectLogoAtPointer;selectLogoAtPointer=function(e,reveal=true){const p=bottomPointerHit(e);if(p&&bottomArtworkAt(p)){if(reveal){setSettingsOpen(true);$('bottomBrandDetails').open=true;bottomPanel.scrollIntoView({block:'nearest'});}templateStatus('Editing Design Mainline bottom branding.');return true;}return bottomOriginalPick(e,reveal);};
async function loadBottomLogo(){try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Could not load the Design Mainline logo.'));i.src='branding/design-mainline.png';});const canvas=document.createElement('canvas');canvas.width=img.width;canvas.height=img.height;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;let x0=img.width,y0=img.height,x1=0,y1=0;for(let y=0;y<img.height;y++)for(let x=0;x<img.width;x++){const i=(y*img.width+x)*4;if(Math.min(data[i],data[i+1],data[i+2])<180){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}}x0=Math.max(0,x0-4);y0=Math.max(0,y0-4);x1=Math.min(img.width-1,x1+4);y1=Math.min(img.height-1,y1+4);const cols=1024,rows=Math.round(cols*(y1-y0+1)/(x1-x0+1));canvas.width=cols;canvas.height=rows;ctx.drawImage(img,x0,y0,x1-x0+1,y1-y0+1,0,0,cols,rows);const pixels=ctx.getImageData(0,0,cols,rows).data,hm=new Float32Array(cols*rows);for(let i=0;i<hm.length;i++)hm[i]=Math.max(0,Math.min(1,(230-Math.min(pixels[i*4],pixels[i*4+1],pixels[i*4+2]))/80));bottomMask={hm,cols,rows};$('bottomBrandEnabled').disabled=false;$('bottomBrandStatus').textContent='Your supplied logo is ready. White background removed.';if(bottomBrand.enabled)requestTemplatePreview();}catch(error){$('bottomBrandStatus').textContent=error.message;}}
syncBottomBrand();loadBottomLogo();

const bottomOriginalRequest=requestTemplatePreview;requestTemplatePreview=function(){if(bottomBrand.enabled&&!bottomMask){templateStatus('Loading the bottom logo…');return;}bottomOriginalRequest();};

function reportBottomPreview(data){if(!bottomBrand.enabled)return;const count=data.info?.affectedByDesign?.at(-1);$('bottomBrandStatus').textContent=data.error?'Bottom preview could not finish: '+data.error:count===0?'The logo is outside the usable bottom area. Click Fit logo to this surface.':count>0?'Logo formed on the '+(bottomBrand.surface==='inside'?'inside bottom':'underside')+' at '+bottomBrand.depthMm.toFixed(2)+' mm.':'Checking bottom placement…';}
